-- VFDA VA Quiz App - Missing cards and VA scope database changes.
-- GENERATED by `npm run db:bundle` from supabase/migrations/. Edit those files, not this one.
-- Paste into the Supabase SQL Editor and run after multiple-doctors.sql.
-- Runs in one transaction: if anything fails, nothing is changed.

begin;

-- ===== 20261106160000_card_gaps_va_scope.sql =====

-- Offices without some cards, and VAs with a limited scope.
--
-- "We don't have this card": a topic of the card upload checklist the office
-- has no card for. It counts as covered for step 2; days fed only by such
-- topics are built from VFDA's master bank and standards, and the gap report
-- lists the missing cards. Any doctor of the office (or VFDA) marks it; the
-- row says who and when.
--
-- "What this VA does": the VA's roles (profiles.va_scope). Null means all of
-- them. Days and workflows outside the roles are skipped (src/lib/va-scope.ts).
--
-- Safe to run more than once.

create table if not exists public.office_card_absences (
  office_id  uuid not null references public.offices (id) on delete cascade,
  card_name  text not null,
  marked_by  uuid references public.profiles (id) on delete set null,
  marked_at  timestamptz not null default now(),
  primary key (office_id, card_name)
);

alter table public.office_card_absences enable row level security;
drop policy if exists "admin manages card absences" on public.office_card_absences;
create policy "admin manages card absences" on public.office_card_absences
  for all to authenticated
  using ((select private.is_admin()))
  with check ((select private.is_admin()));
drop policy if exists "doctor reads own card absences" on public.office_card_absences;
create policy "doctor reads own card absences" on public.office_card_absences
  for select to authenticated
  using (private.is_doctor_of_office(office_id));
drop policy if exists "doctor marks own card absences" on public.office_card_absences;
create policy "doctor marks own card absences" on public.office_card_absences
  for insert to authenticated
  with check (private.is_doctor_of_office(office_id) and marked_by = (select auth.uid()));
drop policy if exists "doctor unmarks own card absences" on public.office_card_absences;
create policy "doctor unmarks own card absences" on public.office_card_absences
  for delete to authenticated
  using (private.is_doctor_of_office(office_id));

alter table public.profiles add column if not exists va_scope text[];
alter table public.profiles drop constraint if exists profiles_va_scope_check;
alter table public.profiles add constraint profiles_va_scope_check
  check (va_scope is null or va_scope <@ array['scheduling', 'phones', 'texting', 'ehr', 'new_patient', 'insurance', 'billing', 'reporting']);

commit;
